(** * NullifierK fixed-base window-point table: builders and materialised literal

    The 85 x 8 = 680 Weierstrass multiples of the NullifierK generator that
    both NullifierK certificates read:

    - the x-coordinate Lagrange certificate
      ([circuit_proof/nullifier_k/x_cert.v]);
    - the positive QR window-sign certificate
      ([circuit_proof/nullifier_k/sign_cert.v]).

    [full_table] builds the multiples through the scalar-multiplication
    composition law (Weierstrass [mul_mul]), by reusing the generic builders
    from [FixedBaseTableDefs] ([nonlast_points], [base_pow8], [last_row],
    [window_offset_sum]), instantiated at the NullifierK generator
    [PallasGenerators.nullifier_k_G].

    [full_table_reduced] is the same table as a pasted affine-coordinate
    literal, generated once offline by [Eval vm_compute in full_table]; the
    equality [full_table_reduced_eq] is the single heavy [vm_compute] [Qed]
    of the NullifierK certificate stack (the octupling chain, evaluated once
    by the kernel's VM).  The two certificate files read only the literal, so
    their own [vm_compute]s cost seconds.

    This file depends only on the elliptic-curve layer (Weierstrass/Pallas),
    the NullifierK generator point ([Orchard.Pallas.Generators]), and the
    shared table builders ([circuit_proof.table_defs]):
    iterating on [Field/Sqrt.v], [ecc/chip/window_disc.v],
    [ecc/chip/fixed_window_canonical.v], or the rest of the Orchard proof
    stack never invalidates it, so the heavy [Qed] re-runs only when the
    curve layer or the generator point itself changes. *)

Require Import Stdlib.ZArith.ZArith.
Require Import Stdlib.Lists.List.
Require Import Garden.EllipticCurve.Weierstrass.
Require Import Garden.EllipticCurve.Pallas.
Require Import Garden.Orchard.Pallas.Generators.
Require Import Garden.Orchard.circuit_proof.table_defs.
Import ListNotations.

Global Open Scope Z_scope.

Module NullifierKFullTable.
  (** The NullifierK affine generator. *)
  Definition G : Pallas.point := PallasGenerators.nullifier_k_G.

  (** All 85 window rows (84 non-last + 1 last), built through the generic
      [FixedBaseTableDefs] octupling-chain builders instantiated at [G]. *)
  Definition full_table : list (list Pallas.point) :=
    FixedBaseTableDefs.nonlast_points 84 G
    ++ [FixedBaseTableDefs.last_row
          (FixedBaseTableDefs.base_pow8 84 G)
          (Pallas.mul (FixedBaseTableDefs.window_offset_sum 84) G)].

